theorem IsMean.posDef
    {w : m → ℝ} {A : m → Matrix n n 𝕜} {t : ℝ} {X : Matrix n n 𝕜}
    (hX : IsMean w A t X) : X.PosDef

theorem Matrix.PosDef.invHalf_conjugate_self {A : Matrix n n 𝕜}
    (hA : A.PosDef) :
    A ^ (-(1 / 2 : ℝ)) * A * A ^ (-(1 / 2 : ℝ)) = 1

theorem Mean.posDef
    {ω : ProbabilityWeights m} {A : m → Matrix n n 𝕜} {t : ℝ}
    (P : Mean ω A t) : P.value.PosDef

theorem compress_mono [Finite k]
    (V : Matrix n k 𝕜) {A B : Matrix n n 𝕜}
    (hAB : A ≤ B) : compress V A ≤ compress V B

theorem matrixIsometry_mul
    {n k l : ℕ} {𝕜 : Type*} [RCLike 𝕜]
    {V : Matrix (Fin n) (Fin k) 𝕜}
    {W : Matrix (Fin k) (Fin l) 𝕜}
    (hV : MatrixIsometry V) (hW : MatrixIsometry W) :
    MatrixIsometry (V * W)

lemma powerCoordinate_nonneg {m : ℕ} {w x : Fin m → ℝ} {t : ℝ}
    (hw : ∀ j, 0 ≤ w j) (hx : ∀ j, 0 ≤ x j) :
    0 ≤ powerCoordinate w x t
